#!/usr/bin/env bash
# R10 shop art, ONE at a time via studio/bin/art.sh. usage: shop.sh [name...]  (FORCE=1 to redo). Process: python proc_shop.py
cd "$(dirname "$0")"
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green walls #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
G="Arrange as a clean grid with wide magenta gaps between items, each item fully visible and the same scale."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }

run shop_coins && g shop_coins "Landscape 3:1 sheet, three game shop items in ONE row, left to right growing in size and richness: (1) a small cream felt drawstring pouch with a few shiny gold coins spilling out, (2) a bigger rust-red burlap sack overflowing with gold coins, a little paw print stitched on it, (3) an open honey-oak treasure chest heaped high with gold coins and a sparkle, gold trim. The gold coins are chunky round with a raised paw print emboss, warm yellow gold #F2B544. $G $K $S"
run shop_offers && g shop_offers "Landscape 3:1 sheet, three game shop items in ONE row: (1) a big gift box wrapped in rust-red paper with a cream satin ribbon bow, lid popped open with gold coins and a small ball of yarn bursting out, (2) a small honey-oak crate with straw, holding a magnifying glass with a paw-shaped lens, a curved rewind arrow token and a soft round cushion, (3) a chunky retro cream television with a big mint-green play triangle on the screen and a little gold coin on top, cute cat ears on the top corners. $G $K $S"
run bg_room_night && g bg_room_night "Portrait 2:3 full-bleed game background, NO magenta. The SAME cozy cat cafe boarding room as a sunny version but at NIGHT: deep navy-teal wall at the top with a bay window upper right showing a starry night sky and a big soft crescent moon, warm string fairy lights draped along the top edge, a wide honey oak table filling the lower 85 percent of the image lit by a warm lamp glow, a hanging pothos plant top-left, a wicker basket with a yarn ball bottom-right, a small potted plant bottom-left. The whole centre of the table is EMPTY, plain evenly lit oak planks, ready for a game board, slightly cooler and dimmer than daytime but still clearly readable. No cats, no characters. $S"
run bg_room_blossom && g bg_room_blossom "Portrait 2:3 full-bleed game background, NO magenta. The SAME cozy cat cafe boarding room in SPRING: soft blush-pink wall at the top with a bay window upper right open onto a pink cherry blossom tree, a few pink petals drifting, a wide pale birch wood table filling the lower 85 percent of the image, a hanging vase of cherry blossom twigs top-left, a wicker basket with a pink yarn ball bottom-right, a small potted tulip bottom-left. The whole centre of the table is EMPTY, plain evenly lit pale wooden planks, ready for a game board. No cats, no characters. $S"
